SELECT 't1' AS tab,quote(a) AS x,quote(b) AS y FROM t1 UNION ALL SELECT 't2',quote(c),quote(d) FROM t2 UNION ALL SELECT 't3',quote(a),quote(b) FROM t3 UNION ALL SELECT 't4',quote(c),quote(d) FROM t4 UNION ALL SELECT 't7',quote(a),quote(b) FROM t7 UNION ALL SELECT 't8',quote(c),quote(d) FROM t8 UNION ALL SELECT 'fk',CAST((SELECT count(*) FROM pragma_foreign_key_check('t1'))+(SELECT count(*) FROM pragma_foreign_key_check('t2'))+(SELECT count(*) FROM pragma_foreign_key_check('t3'))+(SELECT count(*) FROM pragma_foreign_key_check('t4'))+(SELECT count(*) FROM pragma_foreign_key_check('t7'))+(SELECT count(*) FROM pragma_foreign_key_check('t8')) AS TEXT),'' ORDER BY 1,2,3